const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = data[0];
const a = data.slice(1, n + 1);

const maxH = Math.max(...a);
let answer = 0;

for (let h = 1; h <= maxH; h++) {
  let inside = false;
  for (let i = 0; i < n; i++) {
    if (a[i] < h) {
      if (!inside) {
        answer++;
        inside = true;
      }
    } else {
      inside = false;
    }
  }
}

console.log(answer);
